def find_path(graph, start, goal):
    # Initialize a dictionary to track visited nodes and their parent nodes
    visited = {}
    parent = {start: None}

    def search(node):
        # If the goal is reached, reconstruct the path and return it
        if node == goal:
            path = []
            while node is not None:
                path.append(node)
                node = parent[node]
            return path[::-1]
        # Mark the current node as visited
        visited[node] = True
        # Explore all neighbors
        for neighbor in graph[node]:
            if neighbor not in visited:
                parent[neighbor] = node
                path = search(neighbor)
                if path is not None:
                    return path
        return None

    # Start the search from the start node
    return search(start)

