def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    def search(graph, current, visited):
        if current == goal:
            return [current]

        visited.add(current)
        path = None
        for neighbor in graph.get(current, []):
            if neighbor not in visited:
                neighbor_path = search(graph, neighbor, visited)
                if neighbor_path:
                    if path is None or len(neighbor_path) < len(path):
                        path = neighbor_path
        return path

    return search(graph, start, set())

