def find_path_dfs(graph, start, goal):
    def dfs(graph, start, goal, path=None, visited=None):
        if path is None:
            path = [start]
        if visited is None:
            visited = set()
        visited.add(start)
        path.append(start)

        if start == goal:
            return path

        for neighbor in graph[start]:
            if neighbor not in visited:
                new_path = dfs(graph, neighbor, goal, path, visited)
                if new_path:
                    return new_path
        return None

    return dfs(graph, start, goal)

